#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Machine epsilon fixed to 2 as per problem statement
    const MACHINE_EPSILON: i32 = 2;

    // Compute the threshold for "close to zero"
    let threshold = tol * MACHINE_EPSILON;

    // Check if all imaginary parts are close to zero
    if arr.iter().all(|c| c.imag.abs() <= threshold) {
        // If all imag parts are close to zero,
        // produce new array with imag parts zeroed out but 
        // keeping real parts unchanged.
        // If already exactly zero, this preserves equality.
        arr.into_iter()
            .map(|c| Complex { real: c.real, imag: 0 })
            .collect()
    } else {
        // Otherwise, return input unchanged
        arr
    }
}